package com.rpb.reservation.workforce;
import com.rpb.reservation.workforce.api.WorkforceLeaveEntitlementController;import com.rpb.reservation.workforce.leave.entitlement.LeaveEntitlementService;import com.rpb.reservation.walkin.api.*;import com.rpb.reservation.walkin.auth.LocalRuntimeSecurityConfiguration;import java.util.*;import org.junit.jupiter.api.Test;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.boot.test.autoconfigure.web.servlet.WebMvcTest;import org.springframework.boot.test.mock.mockito.MockBean;import org.springframework.context.annotation.Import;import org.springframework.test.context.ActiveProfiles;import org.springframework.test.context.TestPropertySource;import org.springframework.test.web.servlet.MockMvc;import static org.mockito.Mockito.*;import static org.mockito.ArgumentMatchers.*;import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;
@WebMvcTest(WorkforceLeaveEntitlementController.class) @Import({LocalRuntimeSecurityConfiguration.class,com.rpb.reservation.appgate.api.AppGateApiErrorMapper.class}) @ActiveProfiles("local") @TestPropertySource(properties="rpb.local-auth.enabled=true")
class WorkforceLeaveEntitlementLocalRuntimeSecurityTest {
 @Autowired MockMvc mvc;@MockBean CurrentActorProvider actors;@MockBean LeaveEntitlementService service;@MockBean com.rpb.reservation.appgate.application.AppGateService gate;@MockBean com.rpb.reservation.appgate.application.AppGateDenialAuditService denialAudit;
 @Test void exactMethodsOnly()throws Exception{when(actors.currentActor()).thenReturn(Optional.of(new CurrentActor(UUID.randomUUID(),UUID.randomUUID(),"staff",Set.of(),Set.of(),Set.of())));String base="/api/v1/stores/"+UUID.randomUUID()+"/workforce";UUID employee=UUID.randomUUID(),command=UUID.randomUUID();mvc.perform(get(base+"/leave-entitlements?year=2026&employeeId="+employee)).andExpect(status().isOk());verify(service).page(any(),any(),eq(employee),eq(2026),isNull());mvc.perform(put(base+"/employees/"+employee+"/leave-entitlements/"+command).header("X-RPB-Workforce","1").contentType("application/json").content("{}")).andExpect(status().isOk());verify(service).save(any(),any(),eq(employee),eq(command),any());mvc.perform(post(base+"/leave-entitlements")).andExpect(status().isForbidden());mvc.perform(delete(base+"/employees/"+employee+"/leave-entitlements/"+command)).andExpect(status().isForbidden());mvc.perform(put(base+"/leave-entitlements/unsupported").contentType("application/json").content("{}")).andExpect(status().isForbidden());}
}
